def _GetMovementDistanceOrDefault(
        targetID, targetRange, action, **kwargs):
    if targetRange is None:
        return GetDefaultDist(action, targetID, **kwargs)
    return targetRange

def is_expired(self):
    if not self.expiration_time:
        return False
    return self.expiration_time - blue.os.GetWallclockTime() < 0

def GetInventoryLocationID(self):
